// lead : opportunité noCRM · page : fiche Notion (avec `properties`) ou null · lignes : corps
// de la fiche (lignesDepuisBlocs) · souci : raison pour laquelle aucune fiche n'a été retenue.
function batirDossier(lead, page, lignes, souci) {
  const manques = [];
  const contact = enteteContact(lead.description);
  let fiche = null;
  let proprietes = {};
  let source = null;

  if (page && lignes && lignes.length) {
    fiche = parserCorps(lignes);
    proprietes = page.properties || {};
    const [nomT, prenomT] = nomPrenomTitre(valeurPropriete(proprietes['Nom client']) || '');
    fiche.client.nom = fiche.client.nom || nomT;
    fiche.client.prenom = fiche.client.prenom || prenomT;
    completerParProprietes(fiche, proprietes);
    fiche.mission.date_chargement = valeurPropriete(proprietes['Date de chargement']);
    source = 'notion';
  }
  if (!fiche) {
    if (souci) manques.push(souci);
    const corps = corpsDuLead(lead.description);
    if (corps.length > 5) {
      fiche = parserCorps(corps);
      source = 'nocrm';
      manques.push('dossier lu dans la description noCRM, pas dans Notion');
    } else {
      fiche = { client: {}, mission: {}, depart: {}, arrivee: {}, notes: [], alertes: [] };
      source = 'aucune';
      manques.push('ni fiche Notion ni corps exploitable dans noCRM');
    }
  }

  const client = fiche.client || {};
  const mission = fiche.mission || {};
  const depart = fiche.depart || {};
  const arrivee = fiche.arrivee || {};
  const nom = contact.nom || client.nom || nomProbable(lead.title);
  const prenom = contact.prenom || client.prenom || '';

  const adresseDepart = normaliserAdresse(depart.adresse_brute);
  const adresseArrivee = normaliserAdresse(arrivee.adresse_brute);
  if (!adresseDepart) manques.push('adresse de depart absente');
  else if (!porteUnNumero(adresseDepart)) manques.push('adresse de depart sans numero de rue — a faire preciser au client');
  if (!adresseArrivee) manques.push("adresse d'arrivee absente");
  else if (!porteUnNumero(adresseArrivee)) manques.push("adresse d'arrivee sans numero de rue — a faire preciser au client");

  const volume = mission.volume_m3 || valeurPropriete(proprietes['Volume (m3)']);
  if (!volume) {
    manques.push('volume absent — la colonne est APRES « Devis envoye », le volume devrait etre ferme : fiche a resynchroniser');
  }

  const sens = sensDossier(adresseDepart, adresseArrivee);
  if (sens === null && adresseDepart && adresseArrivee) manques.push('sens indetermine (ni depart ni arrivee en Ile-de-France)');

  let fenetre = { tot: null, tard: null };
  const dc = (proprietes['Date de chargement'] || {}).date;
  if (dc && dc.start) fenetre = { tot: dc.start.slice(0, 10), tard: (dc.end || dc.start).slice(0, 10) };
  if (!fenetre.tot) fenetre = { tot: mission.date_chargement || null, tard: mission.date_chargement || null };
  if (!fenetre.tot) manques.push('fenetre de chargement absente');

  const chiffres = {
    ttc: valeurPropriete(proprietes['Prix Total TTC']),
    transport_ht: valeurPropriete(proprietes['Transport HT']),
    deplacement_ht: valeurPropriete(proprietes['Déplacement HT']),
  };
  if (!chiffres.ttc) chiffres.ttc = lead.amount ?? null;
  if (!chiffres.transport_ht) manques.push('ligne Transport HT absente — marge de tournee non calculable sur ce dossier');

  return {
    nocrm_id: lead.id,
    titre_nocrm: lead.title,
    ref: valeurPropriete(proprietes['Réf']),
    nom,
    prenom,
    nom_complet: `${prenom} ${nom}`.trim(),
    email: contact.email || client.email || null,
    tel: contact.tel || client.tel || null,
    sens,
    volume_m3: volume || null,
    depart: { ...depart, adresse: adresseDepart },
    arrivee: { ...arrivee, adresse: adresseArrivee },
    stocke_depot: stockeAuDepot(mission, depart),
    fenetre,
    chiffres,
    date_intervention: mission.date_intervention || null,
    notes: fiche.notes || [],
    alertes: fiche.alertes || [],
    source,
    notion_id: page ? page.id : null,
    notion_url: page ? page.url || null : null,
    manques,
  };
}

// Règles de la mémoire du système : un dossier lu dans le CRM devient deux arrêts
// (chargement et livraison), et un import ne doit JAMAIS écraser ce que Karim a posé à la main.
// Fonctions pures : servent aux nœuds Code (WF1, WF2) et aux tests.

// Champs qu'un import a le droit de rafraîchir. Tout le reste appartient à la page.
const CHAMPS_IMPORT = [
  'client', 'telephone', 'email', 'notionId', 'ref', 'sens', 'volume', 'stockeDepot',
  'fenetreTot', 'fenetreTard', 'acces', 'notes', 'manques', 'transportHt', 'deplacementHt', 'ttc',
];

// Champs posés par la page, le formulaire client ou la veille mail : intouchables à l'import.
const CHAMPS_MANUELS = [
  'groupage', 'ordre', 'jour', 'heureFigee', 'creneauCalcule', 'creneauEnvoye', 'statutClient',
  'contraintes', 'jeton', 'derniereReponse', 'margeMin', 'adresseManuelle', 'lat', 'lon', 'stockeLocal',
];

const texte = (v) => (v === null || v === undefined ? '' : String(v));
const nombre = (v) => (v === null || v === undefined || v === '' ? null : Number(v));

function jeton(alea = Math.random) {
  let s = '';
  while (s.length < 24) s += Math.floor(alea() * 36 ** 8).toString(36).padStart(8, '0');
  return s.slice(0, 24);
}

function accesDe(lieu) {
  return JSON.stringify({
    typeLogement: (lieu || {}).type_logement ?? null,
    etage: (lieu || {}).etage ?? null,
    ascenseur: (lieu || {}).ascenseur ?? null,
    ascenseurPetit: (lieu || {}).ascenseur_petit ?? null,
    rdc: Boolean((lieu || {}).rdc),
    duplex: Boolean((lieu || {}).duplex),
    portageM: (lieu || {}).portage_m ?? null,
    monteMeuble: (lieu || {}).monte_meuble ?? null,
  });
}

function statutAdresse(adresse, porteUnNumero) {
  if (!adresse) return 'manquante';
  return porteUnNumero(adresse) ? 'ok' : 'a_verifier';
}

// Un dossier (batirDossier) → ses deux arrêts. `porteUnNumero` est injecté pour garder ce
// module indépendant de fiche.js côté nœud Code.
function arretsDepuisDossier(dossier, porteUnNumero) {
  const commun = {
    leadId: texte(dossier.nocrm_id),
    client: dossier.nom_complet || '',
    telephone: dossier.tel || '',
    email: dossier.email || '',
    notionId: dossier.notion_id || '',
    ref: texte(dossier.ref),
    sens: dossier.sens || '',
    volume: nombre(dossier.volume_m3),
    stockeDepot: Boolean(dossier.stocke_depot),
    fenetreTot: dossier.fenetre ? dossier.fenetre.tot || '' : '',
    fenetreTard: dossier.fenetre ? dossier.fenetre.tard || '' : '',
    notes: JSON.stringify(dossier.notes || []),
    manques: JSON.stringify(dossier.manques || []),
    transportHt: nombre((dossier.chiffres || {}).transport_ht),
    deplacementHt: nombre((dossier.chiffres || {}).deplacement_ht),
    ttc: nombre((dossier.chiffres || {}).ttc),
  };
  return [
    {
      ...commun,
      type: 'chargement',
      adresse: dossier.depart.adresse || '',
      adresseStatut: statutAdresse(dossier.depart.adresse, porteUnNumero),
      acces: accesDe(dossier.depart),
    },
    {
      ...commun,
      type: 'livraison',
      adresse: dossier.arrivee.adresse || '',
      adresseStatut: statutAdresse(dossier.arrivee.adresse, porteUnNumero),
      acces: accesDe(dossier.arrivee),
    },
  ];
}

const cle = (a) => `${a.leadId}|${a.type}`;

// Confronte ce que dit le CRM à ce que porte la base.
// Rend { aCreer, aMettreAJour, aSupprimer } : les arrêts d'un dossier sorti de la colonne ne
// sont supprimés que s'ils ne sont affectés à aucune tournée — une tournée en cours reste intacte.
function fusionnerImport(arretsLus, arretsExistants, maintenant = new Date().toISOString()) {
  const parCle = new Map((arretsExistants || []).map((a) => [cle(a), a]));
  const vus = new Set();
  const aCreer = [];
  const aMettreAJour = [];

  for (const lu of arretsLus || []) {
    vus.add(cle(lu));
    const existant = parCle.get(cle(lu));
    if (!existant) {
      aCreer.push({
        ...lu,
        groupage: '',
        ordre: 0,
        jour: '',
        heureFigee: '',
        creneauCalcule: '',
        creneauEnvoye: '',
        statutClient: 'a_informer',
        contraintes: '',
        jeton: jeton(),
        derniereReponse: '',
        margeMin: null,
        adresseManuelle: false,
        lat: null,
        lon: null,
        majLe: maintenant,
      });
      continue;
    }
    const maj = { id: existant.id };
    let change = false;
    for (const champ of CHAMPS_IMPORT) {
      // Une adresse corrigée à la main ou par le client ne se fait pas écraser par le CRM.
      if (champ === 'adresse' || (existant.adresseManuelle && champ === 'acces')) continue;
      if (texte(lu[champ]) !== texte(existant[champ])) {
        maj[champ] = lu[champ];
        change = true;
      }
    }
    if (!existant.adresseManuelle && texte(lu.adresse) !== texte(existant.adresse)) {
      maj.adresse = lu.adresse;
      maj.adresseStatut = lu.adresseStatut;
      maj.lat = null; // l'adresse a bougé : le géocodage est à refaire
      maj.lon = null;
      change = true;
    }
    if (!existant.jeton) {
      maj.jeton = jeton();
      change = true;
    }
    if (change) {
      maj.majLe = maintenant;
      aMettreAJour.push(maj);
    }
  }

  const aSupprimer = (arretsExistants || [])
    .filter((a) => !vus.has(cle(a)) && !texte(a.groupage))
    .map((a) => a.id);

  return { aCreer, aMettreAJour, aSupprimer };
}

// --- Enregistrement depuis la page -----------------------------------------------------

const CHAMPS_MODIFIABLES = ['groupage', 'ordre', 'jour', 'heureFigee', 'creneauCalcule', 'creneauEnvoye', 'stockeLocal',
  'statutClient', 'contraintes', 'margeMin', 'adresse', 'adresseStatut', 'adresseManuelle'];

const CHAMPS_TOURNEE = ['nom', 'axe', 'statut', 'dateDebut', 'dateFin', 'camion', 'jours', 'marges'];

const STATUTS_TOURNEE = ['brouillon', 'confirmee', 'en_cours', 'terminee'];

function cleTournee(dateDebut, axe, existantes = []) {
  const court = sansDiacritiques(axe)
    .split(/[^a-z0-9]+/)
    .filter(Boolean)
    .map((m) => m.slice(0, 3))
    .join('-');
  const base = `${(dateDebut || '').slice(0, 10) || 'sans-date'}-${court || 'axe'}`;
  let cleFinale = base;
  let n = 2;
  const prises = new Set(existantes.map((t) => t.cle));
  while (prises.has(cleFinale)) cleFinale = `${base}-${n++}`;
  return cleFinale;
}

function sansDiacritiques(s) {
  return String(s || '').normalize('NFD').replace(/\p{Mn}/gu, '').toLowerCase();
}

// Contrôle de version : deux personnes sur la même tournée ne doivent pas s'écraser.
// Rend { ok } ou { ok: false, code, message } destiné à une réponse HTTP 409.
function verifierVersion(tourneeEnBase, versionAttendue) {
  if (!tourneeEnBase) return { ok: false, code: 404, message: "Cette tournée n'existe plus." };
  const enBase = Number(tourneeEnBase.version || 0);
  if (Number(versionAttendue) !== enBase) {
    return {
      ok: false,
      code: 409,
      message: `Le plan a été modifié entre-temps (version ${enBase}, la page a la ${versionAttendue})`
        + `${tourneeEnBase.modifiePar ? ` par ${tourneeEnBase.modifiePar}` : ''} — recharge la page avant d'enregistrer.`,
    };
  }
  return { ok: true };
}

// Prépare l'écriture d'un enregistrement : ne laisse passer que les champs modifiables.
function preparerEnregistrement(charge, tourneeEnBase, qui, maintenant = new Date().toISOString()) {
  const v = verifierVersion(tourneeEnBase, charge.version);
  if (!v.ok) return v;

  const tournee = { id: tourneeEnBase.id, version: Number(tourneeEnBase.version || 0) + 1, modifiePar: qui || '', modifieLe: maintenant };
  for (const champ of CHAMPS_TOURNEE) {
    if (charge.tournee && charge.tournee[champ] !== undefined) tournee[champ] = charge.tournee[champ];
  }
  if (tournee.statut && !STATUTS_TOURNEE.includes(tournee.statut)) {
    return { ok: false, code: 400, message: `Statut de tournée inconnu : ${tournee.statut}` };
  }

  const arrets = [];
  for (const a of charge.arrets || []) {
    if (!a.id) return { ok: false, code: 400, message: 'Un arrêt sans identifiant ne peut pas être enregistré.' };
    const ligne = { id: a.id, majLe: maintenant };
    for (const champ of CHAMPS_MODIFIABLES) if (a[champ] !== undefined) ligne[champ] = a[champ];
    arrets.push(ligne);
  }
  return { ok: true, tournee, arrets };
}


