// toujours le code postal, alors que l'adresse saisie l'oublie souvent — « 10 rue de l'Asile,
// Bordeaux » n'en a pas, et se retrouvait donc hors de toute région, donc hors calcul.
function regionDuPoint(point, adresse) {
  const cp = codePostal((point || {}).libelle) || codePostal(adresse);
  if (!cp) return null;
  const dept = cp.slice(0, 2);
  if (DEPTS_IDF.includes(dept)) return 'idf';
  if (DEPTS_GIRONDE.includes(dept)) return 'gironde';
  return null;
}

// Requête de repli pour situer au moins la commune : la ville et son code postal, sans la voie.
// Envoyer l'adresse entière ne donne rien quand elle porte une résidence, un bâtiment et un étage.
