const ABREVIATIONS = {
  av: 'avenue', ave: 'avenue', bd: 'boulevard', bld: 'boulevard', r: 'rue', all: 'allee',
  pl: 'place', imp: 'impasse', ch: 'chemin', che: 'chemin', rte: 'route', crs: 'cours',
  sq: 'square', pass: 'passage', qu: 'quai', res: 'residence', lot: 'lotissement',
  st: 'saint', ste: 'sainte',
};

const MOTS_VIDES = new Set(['de', 'du', 'des', 'la', 'le', 'les', 'l', 'd', 'et', 'a', 'au', 'aux']);

const TYPES_VOIE = new Set(['rue', 'avenue', 'boulevard', 'allee', 'place', 'impasse', 'chemin',
  'route', 'cours', 'square', 'passage', 'quai', 'residence', 'lotissement', 'voie', 'sentier',
  'esplanade', 'promenade', 'villa', 'cite', 'hameau', 'parvis', 'mail', 'clos', 'domaine',
  'venelle', 'rond-point']);

function jetons(texte) {
  const nu = String(texte || '').toLowerCase().normalize('NFD').replace(/\p{Mn}/gu, '');
  return nu.split(/[^a-z0-9]+/).filter((m) => m && !MOTS_VIDES.has(m)).map((m) => ABREVIATIONS[m] || m);
}

// « 12 Allée Maurice Carême, 95100 Argenteuil » → « Allée Maurice Carême ».
// null quand la saisie ne porte aucune voie (« Wissous, 91320 ») : il n'y a rien à vérifier.
const COMPLEMENT = /\s+(?:résidence|residence|rés\.|res\.|bâtiment|batiment|bât\.?|bat\.|appartement|appt|apt|escalier|esc\.|étage|etage)(?=[\s.,]|$).*$/i;

function voieSaisie(adresse) {
  let premier = String(adresse || '').split(',')[0];
  premier = premier.replace(/\b\d{5}\b.*$/, '');
  premier = premier.replace(/^\s*\d{1,4}\s*(bis|ter|[a-d])?\b\s*/i, '');
  // « 22 Rue Camille Maumey Résidence Les Lierres » : la résidence complète l'adresse, elle
  // n'est pas la voie — la garder fait rejeter la bonne rue à la vérification de concordance.
  premier = premier.replace(COMPLEMENT, '');
  const mots = jetons(premier);
  const porteUnType = mots.some((m) => TYPES_VOIE.has(m));
  if (!mots.length || !(porteUnType || /^\s*\d/.test(String(adresse || '')))) return null;
  return premier.trim() || null;
}

function numeroSaisi(adresse) {
  return /^\s*\d{1,4}\s*(bis|ter|[a-d])?\b/i.test(String(adresse || '').split(',')[0]);
}

// La voie trouvée est-elle celle qui a été saisie ? Tous les mots significatifs de la saisie
// doivent figurer dans le libellé rendu, type de voie compris : « Allée Maurice Carême » ne
// concorde ni avec « Avenue Maurice Utrillo », ni avec « Rue Maurice Carême ».
function voieConcorde(voie, libelle) {
  if (!voie) return true;
  const attendu = jetons(voie);
  if (!attendu.length) return false;
  const rendus = new Set(jetons(libelle));
  return attendu.every((m) => rendus.has(m));
}

// Verdict sur un point géocodé. Deux questions distinctes, qu'on ne mélange pas :
// l'adresse du CLIENT est-elle complète, et NOTRE point de calcul est-il précis ?
function qualiteAdresse(point) {
  if (!point || point.erreur || point.lat === null || point.lat === undefined) return 'introuvable';
  if (point.voieSaisie === false) return 'ville_seule';
  if (point.introuvable || point.voieVerifiee === false) return 'introuvable';
  if (point.numeroSaisi === false) return 'sans_numero';
  if (point.precision === 'housenumber') return 'exacte';
  return 'rue_localisee';
}

